-- StreakFit: least-privilege runtime role (Phase B-2, incident 2026-10-13).
-- Run as neondb_owner in the TARGET project's SQL editor, after confirming:
--     select current_setting('neon.endpoint_id', true);   -- must be the intended endpoint
-- The password is generated by the owner locally and pasted in place of the
-- placeholder; it is never committed, logged or shared in chat. In psql:
--     \set app_password `python3 -c "import secrets;print(secrets.token_urlsafe(48))"`
-- and replace '<APP_PASSWORD>' with :'app_password'.
-- Idempotent except CREATE ROLE (re-running after success fails on it; that is fine).

begin;
create role streakfit_app login password '<APP_PASSWORD>'
  nosuperuser nocreatedb nocreaterole noreplication nobypassrls inherit;
do $$ begin execute format('grant connect on database %I to streakfit_app', current_database()); end $$;
grant usage on schema public to streakfit_app;
grant select, insert, update, delete on all tables in schema public to streakfit_app;
grant usage, select on all sequences in schema public to streakfit_app;
revoke insert, update, delete, truncate on alembic_version from streakfit_app;
alter default privileges for role neondb_owner in schema public
  grant select, insert, update, delete on tables to streakfit_app;
alter default privileges for role neondb_owner in schema public
  grant usage, select on sequences to streakfit_app;
commit;
